// Every raster asset is pre-generated by Shed Dev Sprites. Vite bundles these URLs.
const assets = import.meta.glob('../public/sprites/*.png', { eager: true, query: '?url', import: 'default' }) as Record<string, string>;
export function spriteUrl(name: string) { return assets[`../public/sprites/${name}.png`]; }
export const IMG = {
  titleBg: spriteUrl('cover'), humanCrest: spriteUrl('human-melee-0'),
  darkelfCrest: spriteUrl('darkelf-melee-0'), corruptedCrest: spriteUrl('corrupted-melee-0'),
  woodPanel: spriteUrl('wood'), victory: spriteUrl('cover'), defeat: spriteUrl('cover'),
};
const images = new Map<string, HTMLImageElement>();
export function sprite(name: string) {
  let img = images.get(name);
  if (!img) { img = new Image(); img.src = spriteUrl(name); images.set(name, img); }
  return img.complete && img.naturalWidth ? img : null;
}
